        Count storage g = _agent[keccak256(bytes(handle))];
        uint256 wm = w.free + w.paid;
        uint256 gm = g.free + g.paid;
        require(wm + quantity <= MAX_PER_WALLET, "Wallet limit");
        require(gm + quantity <= MAX_PER_AGENT, "Agent ID limit");
